export const getTestByName = (testName: string | null): TestConfig | null => {
  if (!testName) return null;
  return allTests[testName] || null;
};

export const getAvailableTests = () => {
  return Object.keys(allTests).map(key => ({
    id: key,
    title: allTests[key].title,
    description: allTests[key].description,
    questionCount: allTests[key].questions.length,
    duration: allTests[key].durationMinutes,
  }));
};
